    /// <summary>Running an action that uses a spell, or a wand's own attack. Worked out by Kiln.</summary>
    Casting = 0x1602,
    /// <summary>Running an action with a used item that is not a weapon. Worked out by Kiln.</summary>
    UsingItem = 0x1603,
    /// <summary>Inside a flame altar's build zone (kiln.build's base list). Worked out by Kiln.</summary>
    InBase = 0x1604,
    /// <summary>The Rested buff is on. Worked out by Kiln.</summary>
    Rested = 0x1605,
    /// <summary>At least one food buff is on. Worked out by Kiln.</summary>
    Fed = 0x1606,
    /// <summary>At least one debuff is on. Worked out by Kiln.</summary>
    HasDebuff = 0x1607,
    /// <summary>The game's hunger marker is in a food slot: nothing eaten (program thirst_and_hunger). Worked out by Kiln.</summary>
    Hungry = 0x1608,

    /// <summary>The same as <see cref="HangGliding"/>.</summary>
    Gliding = HangGliding,
    /// <summary>The same as <see cref="UnderWater"/>.</summary>
    Underwater = UnderWater,
    /// <summary>The same as <see cref="InSneakMode"/>.</summary>
    Sneaking = InSneakMode,
    /// <summary>The same as <see cref="InFog"/>.</summary>
    InShroud = InFog,
    /// <summary>The same as <see cref="InSaveZone"/>.</summary>
    InSafeZone = InSaveZone,
    /// <summary>The same as <see cref="LocomotionSwimming"/>.</summary>
    Swimming = LocomotionSwimming,
    /// <summary>The same as <see cref="LocomotionDiving"/>.</summary>
    Diving = LocomotionDiving,
    /// <summary>The same as <see cref="LocomotionSliding"/>.</summary>
    Sliding = LocomotionSliding,
    /// <summary>The same as <see cref="LocomotionClimbingWall"/>.</summary>
    ClimbingWall = LocomotionClimbingWall,
    /// <summary>The same as <see cref="LocomotionClimbingLadder"/>.</summary>
    ClimbingLadder = LocomotionClimbingLadder,
    /// <summary>The same as <see cref="IsSprinting"/>.</summary>
    Sprinting = IsSprinting,
    /// <summary>The same as <see cref="AttachedToHook"/>.</summary>
