}

/// <summary>Where a state comes from. The game's own enum names its values.</summary>
public enum PlayerStateSource : byte
{
    None = 0,
    /// <summary><c>keen::actor::StateFlag</c> in <c>Actor.currentState</c>.</summary>
    Actor = 1,
    /// <summary><c>keen::ecs::LocomotionState</c> in <c>DynamicLocomotion.state</c>.</summary>
    Locomotion = 2,
    /// <summary><c>keen::ecs::PlayerFlags</c> in <c>PlayerState.playerStateMask</c>.</summary>
    Player = 3,
    /// <summary><c>keen::ecs::LocomotionFlags</c> in <c>DynamicLocomotion.flags</c>.</summary>
    Motion = 4,
    /// <summary><c>keen::ecs::ClientPlayerFlags</c> in <c>PlayerInput.fromClient.mask</c>.</summary>
    ClientUi = 5,
    /// <summary><c>keen::actor::AbilityFlag</c> in <c>Actor.currentAbilityMask</c>.</summary>
    Ability = 6,
    /// <summary><c>keen::ecs::PlayerInputType</c> in <c>PlayerInput.fromClient.digitalInput</c>.</summary>
    Input = 7,
    /// <summary><c>keen::actor::ActionSequenceTrigger</c> in <c>Actor.currentAction.triggerContext.triggerType</c>.</summary>
    Action = 8,
    /// <summary><c>keen::actor::JumpType</c> in <c>DynamicLocomotion.jumpType</c>.</summary>
    Jump = 9,
    /// <summary><c>keen::ecs::LocomotionSpeedSelector</c> in <c>ActorInput.lastLocomotionSpeed</c>.</summary>
    Speed = 10,
    /// <summary><c>keen::ecs::ColliderMode</c> in <c>Actor.currentColliderMode</c>.</summary>
    Collider = 11,
    /// <summary><c>keen::ecs::ClimbState</c> in <c>Climb.climbState</c>.</summary>
    Climb = 12,
    /// <summary><c>keen::ecs::ClimbType</c> in <c>Climb.climbType</c>.</summary>
    ClimbType = 13,
    /// <summary><c>keen::ecs::HookShotState</c> in <c>HookShot.hookShotState</c>.</summary>
    Hook = 14,
    /// <summary><c>keen::ecs::HookShotType</c> in <c>HookShot.hookShotType</c>.</summary>
    HookType = 15,
    /// <summary><c>keen::ranged_weapon::State</c> in <c>NetworkRangedWeapon.currentState</c>.</summary>
    Ranged = 16,
    /// <summary><c>keen::fishing::State</c> in <c>NetworkFishing.state</c>.</summary>
    Fishing = 17,
    /// <summary><c>keen::ecs::CookingFlags</c> in <c>NetworkCookingData.mask</c>.</summary>
    CookingFlag = 18,
    /// <summary><c>keen::ecs::ReviveState</c> in <c>NetworkPlayerAttributes.revivieData.state</c>.</summary>
    Revive = 19,
    /// <summary><c>keen::FogType</c> in <c>EnvironmentSensor.fogType</c>.</summary>
    Fog = 20,
    /// <summary><c>keen::TemperatureVoxelType</c> in <c>EnvironmentSensor.temperature</c>.</summary>
    Temperature = 21,
    /// <summary>Worked out by Kiln from the other sources.</summary>
    Derived = 22,
}

